[CmdletBinding()]
param([string]$PlanPath,[string]$Root=(Get-Location).Path,[string]$StatePath=(Join-Path $Root 'ops/execution/repository-state.json'))
$ErrorActionPreference='Stop';$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json -Depth 100;$items=@()
foreach($work in @($plan.items)){$r=[ordered]@{id=$work.id;state='RECEIVED';error=$null;evidenceVerified=$false};if($work.executionClass -eq 'EXTERNAL'){$r.state='BLOCKED_EXTERNAL';$items+=[pscustomobject]$r;continue};try{$script=if([IO.Path]::IsPathRooted($work.script)){$work.script}else{Join-Path $Root $work.script};if(-not(Test-Path $script)){throw "Executor missing: $($work.script)"};$r.state='EXECUTING';& $script @($work.arguments)|Out-Null;if($LASTEXITCODE -ne 0){throw "Exit code $LASTEXITCODE"};foreach($e in @($work.evidence)){if(-not(Test-Path (Join-Path $Root $e))){throw "Evidence missing: $e"}};$r.evidenceVerified=$true;$r.state='COMPLETE'}catch{$r.state='FAILED';$r.error=$_.Exception.Message};$items+=[pscustomobject]$r}
$state=[ordered]@{schemaVersion='1.0.0';generatedAt=[DateTime]::UtcNow.ToString('o');status=if(@($items|? state -eq 'FAILED').Count){'FAILED'}elseif(@($items|? state -eq 'BLOCKED_EXTERNAL').Count){'BLOCKED_EXTERNAL'}else{'COMPLETE'};items=$items};$state|ConvertTo-Json -Depth 100|Set-Content -LiteralPath $StatePath -Encoding utf8;$state;if($state.status -eq 'FAILED'){exit 1};exit 0
